/* VCAM PRO — download centre data binding.
 *
 * The page reads the published releases straight from the public GitHub API, so
 * it always matches what is actually released. `release.json` (generated by the
 * deploy workflow) and the Releases page are only fallbacks when the API cannot
 * be reached (offline, rate limit).
 */
(function () {
  'use strict';

  var REPO = 'MPV999/vcam-pro-2026';
  var API = 'https://api.github.com/repos/' + REPO;
  var RELEASES_URL = 'https://github.com/' + REPO + '/releases';

  var state = { release: null, releases: [], source: '' };

  function $(id) { return document.getElementById(id); }

  function formatBytes(bytes) {
    var value = Number(bytes) || 0;
    if (value <= 0) return '—';
    if (value >= 1073741824) return (value / 1073741824).toFixed(2) + ' GB';
    if (value >= 1048576) return (value / 1048576).toFixed(1) + ' MB';
    if (value >= 1024) return Math.round(value / 1024) + ' KB';
    return value + ' B';
  }

  function formatDate(iso) {
    if (!iso) return '—';
    var date = new Date(iso);
    if (isNaN(date.getTime())) return '—';
    return date.toLocaleDateString('vi-VN', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  function escapeHtml(text) {
    return String(text == null ? '' : text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  /** 1.0.8 -> 10008, so the version code is meaningful even without a body. */
  function versionCodeFromTag(tag) {
    var parts = String(tag || '')
      .replace(/^v/i, '')
      .split(/[.\-+_]/)
      .map(function (part) { return parseInt(part, 10); })
      .filter(function (part) { return !isNaN(part); });
    while (parts.length < 3) parts.push(0);
    return parts[0] * 10000 + parts[1] * 100 + parts[2];
  }

  function findAsset(assets, pattern) {
    for (var i = 0; i < assets.length; i += 1) {
      if (pattern.test(assets[i].name || '')) return assets[i];
    }
    return null;
  }

  function releaseFromApi(json) {
    var tag = String(json.tag_name || '').replace(/^v/i, '');
    var assets = json.assets || [];
    var apk = findAsset(assets, /\.apk$/i);
    var sums = findAsset(assets, /sha256/i);
    var body = json.body || '';

    var shaMatch = body.match(/SHA-?256:?\s*([0-9a-fA-F]{64})/);
    var codeMatch = body.match(/Version\s*code\s*\|?\s*(\d+)/i);
    var bodyCode = codeMatch ? parseInt(codeMatch[1], 10) : 0;
    var debugSigned = /khoá debug|khoa debug|debug-signed|debug signing/i.test(body);

    return {
      published: !!(tag && apk),
      version: tag,
      versionCode: bodyCode > 0 ? bodyCode : versionCodeFromTag(tag),
      apkName: apk ? apk.name : '',
      apkSize: apk ? apk.size : 0,
      sha256: shaMatch ? shaMatch[1].toLowerCase() : '',
      minAndroid: 'Android 10 (API 29)',
      abis: ['arm64-v8a', 'armeabi-v7a'],
      releaseDate: json.published_at || json.created_at || '',
      releaseUrl: json.html_url || RELEASES_URL,
      downloadUrl: apk ? apk.browser_download_url : '',
      sumsUrl: sums ? sums.browser_download_url : '',
      signed: !debugSigned,
      notes: body
    };
  }

  function renderPending(reason) {
    var stateEl = $('dlState');
    if (stateEl) {
      stateEl.textContent = 'Chưa đọc được bản phát hành';
      stateEl.classList.add('pending');
    }
    var hint = $('dlHint');
    if (hint) {
      hint.textContent = (reason ? reason + ' ' : '') +
        'Bạn vẫn có thể tải trực tiếp trên trang Releases.';
    }
    var button = $('dlButton');
    if (button) {
      button.textContent = 'Mở trang Releases';
      button.href = RELEASES_URL;
      button.setAttribute('rel', 'noopener');
    }
    var hero = $('heroDownload');
    if (hero) hero.href = RELEASES_URL;
    var heroVersion = $('heroVersion');
    if (heroVersion) heroVersion.textContent = 'Xem các bản phát hành trên GitHub.';
    var link = $('dlReleaseLink');
    if (link) link.href = RELEASES_URL;
  }

  function render() {
    var release = state.release;
    var published = !!(release && release.published && release.version);

    if (!published) {
      renderPending('');
      renderNotes(null);
      return;
    }

    if ($('dlVersion')) $('dlVersion').textContent = 'v' + release.version;
    if ($('dlCode')) $('dlCode').textContent = release.versionCode ? String(release.versionCode) : '—';
    if ($('dlFile')) $('dlFile').textContent = release.apkName || '—';
    if ($('dlSize')) $('dlSize').textContent = formatBytes(release.apkSize);
    if ($('dlMin')) $('dlMin').textContent = release.minAndroid || 'Android 10 (API 29)';
    if ($('dlAbi')) $('dlAbi').textContent = (release.abis || ['arm64-v8a', 'armeabi-v7a']).join(', ');
    if ($('dlDate')) $('dlDate').textContent = formatDate(release.releaseDate);
    if ($('dlSha')) $('dlSha').textContent = release.sha256 || '—';

    var stateEl = $('dlState');
    if (stateEl) {
      stateEl.classList.remove('pending');
      if (!release.signed) {
        stateEl.textContent = 'Bản dựng chưa ký phát hành';
        stateEl.classList.add('pending');
      } else {
        stateEl.textContent = 'Đã phát hành';
      }
    }

    var button = $('dlButton');
    if (button) {
      if (release.downloadUrl) {
        button.textContent = 'Tải APK ' + (release.apkName || '');
        button.href = release.downloadUrl;
        button.setAttribute('rel', 'noopener');
      } else {
        button.textContent = 'Xem bản phát hành';
        button.href = release.releaseUrl || RELEASES_URL;
      }
    }

    var hint = $('dlHint');
    if (hint) {
      var source = state.source === 'api'
        ? 'Dữ liệu đọc trực tiếp từ GitHub Releases.'
        : 'Dữ liệu đọc từ release.json của trang.';
      hint.textContent = release.signed
        ? source + ' APK được CI dựng từ mã nguồn, ký release và kiểm tra bằng apksigner.'
        : source + ' APK được CI dựng và ký bằng khoá debug để cài được ngay; bản ký phát hành chính thức cần signing secrets (xem docs/BUILD.md).';
    }

    var heroVersion = $('heroVersion');
    if (heroVersion) {
      heroVersion.textContent = 'Phiên bản ' + release.version +
        (release.apkSize ? ' · ' + formatBytes(release.apkSize) : '') +
        ' · phát hành ' + formatDate(release.releaseDate);
    }
    var hero = $('heroDownload');
    if (hero) {
      if (release.downloadUrl) {
        hero.href = release.downloadUrl;
        hero.textContent = 'Tải APK ' + release.version;
        hero.setAttribute('rel', 'noopener');
      } else {
        hero.href = RELEASES_URL;
      }
    }
    var link = $('dlReleaseLink');
    if (link) link.href = release.releaseUrl || RELEASES_URL;

    renderNotes(release);
    renderHistory();
  }

  function renderNotes(release) {
    var notesEl = $('dlNotes');
    var releaseNotes = $('releaseNotes');
    var text = release && release.notes ? release.notes : '';
    if (!text) {
      var empty = '<p class="muted">Chưa có ghi chú phát hành.</p>';
      if (notesEl) notesEl.innerHTML = empty;
      if (releaseNotes) releaseNotes.innerHTML = empty;
      return;
    }

    var lines = text.split(/\r?\n/);
    var html = [];
    var paragraph = [];

    function flush() {
      if (paragraph.length === 0) return;
      var joined = paragraph.join('<br>');
      joined = joined.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
      joined = joined.replace(/`([^`]+)`/g, '<code>$1</code>');
      html.push('<p>' + joined + '</p>');
      paragraph = [];
    }

    lines.forEach(function (raw) {
      var line = escapeHtml(raw).trim();
      if (/^\|?[\s:|-]+\|[\s:|-]*$/.test(line)) return;
      if (line.indexOf('#') === 0) {
        flush();
        html.push('<h3>' + line.replace(/^#+\s*/, '') + '</h3>');
        return;
      }
      if (line === '') {
        flush();
        return;
      }
      paragraph.push(line);
    });
    flush();

    var output = html.join('');
    if (notesEl) notesEl.innerHTML = output;
    if (releaseNotes) releaseNotes.innerHTML = output;
  }

  function renderHistory() {
    var table = $('historyTable');
    if (!table) return;
    var body = table.querySelector('tbody');
    if (!body) return;
    if (!state.releases.length) return;

    body.innerHTML = state.releases.map(function (release) {
      var version = String(release.tag_name || '').replace(/^v/i, '');
      var debug = /khoá debug|khoa debug|debug-signed|debug signing/i.test(release.body || '');
      var apk = findAsset(release.assets || [], /\.apk$/i);
      return '<tr><td><a href="' + escapeHtml(release.html_url || RELEASES_URL) +
        '" target="_blank" rel="noopener">v' + escapeHtml(version) + '</a></td><td>' +
        escapeHtml(String(versionCodeFromTag(version))) + '</td><td>' +
        formatDate(release.published_at || release.created_at) + '</td><td>' +
        (debug ? 'Bản dựng CI, ký debug' : 'Bản phát hành chính thức') +
        (apk ? ' · ' + formatBytes(apk.size) : '') + '</td></tr>';
    }).join('');
  }

  function getJson(url) {
    return fetch(url, {
      cache: 'no-store',
      headers: { Accept: 'application/vnd.github+json' }
    }).then(function (response) {
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return response.json();
    });
  }

  function loadFromApi() {
    return getJson(API + '/releases/latest').then(function (json) {
      state.release = releaseFromApi(json);
      state.source = 'api';
      render();
      return getJson(API + '/releases?per_page=8').then(function (list) {
        state.releases = (list || []).filter(function (item) { return !item.draft; });
        renderHistory();
      }).catch(function () { /* history is optional */ });
    });
  }

  function loadFromFile() {
    return fetch('release.json', { cache: 'no-store' })
      .then(function (response) {
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      })
      .then(function (json) {
        state.release = json;
        state.source = 'file';
        render();
      });
  }

  function load() {
    loadFromApi().catch(function (apiError) {
      loadFromFile().catch(function () {
        renderPending('GitHub API: ' + apiError.message + '.');
      });
    });
  }

  function wire() {
    var toggle = $('navToggle');
    var links = $('navLinks');
    if (toggle && links) {
      toggle.addEventListener('click', function () { links.classList.toggle('open'); });
      links.addEventListener('click', function (event) {
        if (event.target.tagName === 'A') links.classList.remove('open');
      });
    }

    var copy = $('copySha');
    if (copy) {
      copy.addEventListener('click', function () {
        var value = $('dlSha') ? $('dlSha').textContent.trim() : '';
        if (!value || value === '—') return;
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(value).then(function () {
            copy.textContent = 'Đã sao chép';
            setTimeout(function () { copy.textContent = 'Sao chép'; }, 1800);
          });
        }
      });
    }

    var year = $('year');
    if (year) year.textContent = String(new Date().getFullYear());

    load();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', wire);
  } else {
    wire();
  }
})();
